/* 60 REAL exam questions converted from the parsed JSON */
window.QUESTIONS = [];
function Q(t, d, c, q, o, a, w, x, k) { window.QUESTIONS.push({ t: t, d: d, c: c, q: q, o: o, a: a, w: w, x: x, k: k }); }
var B = 'Beginner', I = 'Intermediate', A = 'Advanced';
var MC = 'Multiple choice', SC = 'Scenario', SEQ = 'Sequence ordering', ST = 'Select two';

/* Topic groupings: Artifacts, Iteration, Workflows, 4Ds, Prompting, Projects, Code Execution, Model Selection, Data Sensitivity, Evaluation */

Q('Artifacts', B, MC, 'A knowledge worker has asked Claude to produce a written procedure that the team will reference across multiple review cycles, and update it when the underlying process changes. Which output format is most appropriate?', [
  'Generate the procedure as the chat response and copy the text into the team\'s document store after each review.',
  'Generate the procedure as a series of numbered steps in the chat and keep the chat itself as the reference for future edits.',
  'Generate the procedure as an Artifact, which the team can open, edit, and save as a stable reference for ongoing use.',
  'Generate the procedure as the chat response and save the entire chat transcript to the team\'s document store as the working reference.'], 2,
  'Artifacts render standalone documents in a dedicated side panel that team members can view, edit, version, and save as a stable reference across review cycles.',
  'Chat responses scroll away and get buried. Saving the whole transcript is unwieldy. Artifacts are designed for reusable team-facing work.', 'Artifact use case');

Q('Iteration', I, ST, 'You are reviewing colleagues\' responses to feedback on a Claude-assisted draft. Which two feedback responses are productive? (Select two.)', [
  'mapping each piece of feedback to the specific change made in the next draft',
  'deferring all feedback to a later revision cycle to avoid disrupting the current draft\'s consistency',
  'asking clarifying questions when feedback is ambiguous before acting on it',
  'declining to revise Claude-generated sections on the basis that the model\'s output should be trusted as written',
  'incorporating all feedback received, including contradictory suggestions, into the next draft simultaneously'], [0, 2],
  'Productive iteration traces each accepted feedback item to a specific revision (A) and clarifies ambiguous feedback before prompting or editing (C).',
  'Deferring all feedback, trusting output blindly, or applying contradictory edits simultaneously are unproductive.', 'Feedback discipline');

Q('Workflows', I, ST, 'You are evaluating proposed workflow changes for a team that runs a recurring Claude workflow. Which two proposed changes meaningfully improve a recurring Claude workflow? (Select two.)', [
  'extracting the standard reference material into a Project to avoid repeating it',
  'labeling each workflow step with descriptive names to improve readability for new team members',
  'reorganizing the workflow document\'s section headings to improve navigation',
  'adding a quality check on outputs before they enter the downstream process',
  'updating the team\'s shared workspace name to reflect the new workflow process'], [0, 3],
  'Recurring workflows improve when shared reference materials are centralized into a Project (A, avoids repetition) and when a quality-verification step gates outputs before downstream use (D).',
  'Labeling steps, reorganizing headings, and renaming workspaces are cosmetic; they do not reduce rework or catch errors.', 'Workflow improvement');

Q('Workflows', I, MC, 'A workflow analyst is designing a hand-off between a Claude-assisted drafting step and a human reviewer. The reviewer needs to know what to check and what is in scope for their review. Which hand-off design is most appropriate?', [
  'Use a checklist that the reviewer fills in for every output, with the checklist generated by Claude based on the specific content of each output.',
  'Define explicit criteria for what Claude produces and what the human reviewer must check before approval, documented in the workflow.',
  'Define explicit criteria for what Claude produces and leave the reviewer\'s checks unspecified so the reviewer can apply judgment without constraint.',
  'Allow each reviewer to determine their own review criteria based on their experience, since reviewers know best what to check in their domain.'], 1,
  'A reliable human-in-the-loop hand-off requires explicitly documenting both what Claude produces and the specific verification criteria the human reviewer must check before approving.',
  'Leaving reviewer checks unspecified or letting each reviewer decide creates inconsistent reviews and missed issues.', 'Hand-off design');

Q('4Ds: Discernment', I, MC, 'You are an analyst fact-checking a Claude-generated report and find that two secondary sources give conflicting dates for the same event. Which approach is correct?', [
  'Choose the more recent date on the basis that later sources typically reflect updated or corrected information.',
  'Use the date confirmed by whichever source carries the more detailed citation for the event.',
  'Average the two conflicting dates and use the average, treating a midpoint as a reasonable stand-in for verification.',
  'Locate a primary or authoritative source for the event and use the date that source confirms.'], 3,
  'When secondary sources conflict, proper fact-checking (Discernment) requires locating a primary or authoritative source to verify the true date.',
  'Guessing (newest, most detailed, averaging) are not verification. Only the primary source confirms truth.', 'Fact-checking discipline');

Q('Connectors', I, MC, 'A knowledge worker used the Google Drive connector with Claude to summarize a recently revised policy document. The summary reflects the prior version of the document, not the revision saved three hours earlier. Which factor most likely explains this?', [
  'The associate\'s permissions on the document allow access only to the prior version, since the revision is held in a separate permission group until publication.',
  'The connector retrieved both versions, and Claude selected the earlier one because it was longer and contained more material relevant to the prompt.',
  'The connector cached the prior version of the document at the start of the chat session, and will continue to use the cached version until the chat is closed.',
  'The connector\'s index has not yet refreshed to reflect the recently revised document, so the older indexed content is still being referenced.'], 3,
  'External workspace connectors rely on an index that refreshes periodically. A revision saved only three hours earlier may not be re-indexed yet, causing Claude to summarize the prior indexed version.',
  'Permissions, length, and session caching are not the issue. Index lag is the most likely cause.', 'Connector index refresh');

Q('Prompting', I, MC, 'A product manager is using Claude to ideate candidate new-feature concepts for an upcoming product roadmap before narrowing and will evaluate trade-offs across the options in a separate session. Which prompting strategy fits this stage?', [
  'Request multiple distinct options and ask Claude to recommend the strongest one with reasoning, so the team starts the trade-off discussion from a leading candidate.',
  'Request multiple distinct options with stated trade-offs, and avoid committing to a single recommendation in this round.',
  'Request a single recommended option with strong reasoning, since well-reasoned single options give the team a clearer starting point than several weakly-reasoned alternatives.',
  'Request multiple distinct options ordered by Claude\'s assessment of feasibility, so the team can focus its trade-off discussion on the most feasible options first.'], 1,
  'During divergent ideation when trade-off evaluation is scheduled later, prompting for multiple distinct candidate options with their stated trade-offs—without locking into a single winner—gives the team a balanced slate to evaluate.',
  'Prematurely recommending one option or ordering by feasibility narrows the options before the team evaluates.', 'Ideation strategy');

Q('Prompting', I, MC, 'You received a vague request to "look at our pricing" and clarified with the requester that the deliverable is a structured competitor-pricing summary the team can act on, not new pricing ideas. Which strategy best fits the clarified task?', [
  'Use a research strategy that gathers structured information about competitor pricing, names sources, and notes confidence on each finding.',
  'Use a divergent brainstorming approach to generate a wide range of possible competitor-pricing observations, then narrow to the most likely ones.',
  'Use a comparative analysis strategy that contrasts the company\'s pricing against a single named competitor, since pairwise comparison produces the clearest output.',
  'Use an open conversational strategy that explores competitor pricing iteratively across several prompts, allowing the structure to emerge from the conversation.'], 0,
  'Once clarified as an actionable competitor-pricing summary, the right approach is a structured research strategy that gathers comparable data, cites sources, and notes confidence levels.',
  'Brainstorming, pairwise comparison, and open conversation do not produce the structured, sourced summary the task requires.', 'Task clarification');

Q('Iteration', B, MC, 'When refining a Claude output that does not meet expectations, which iterative refinement step should be performed first?', [
  'Modify the prompt to address each identified weakness.',
  'Compare the new output against the original criteria.',
  'Submit the revised prompt and capture the new output.',
  'Identify the specific weaknesses in the current output.'], 3,
  'Before modifying the prompt (A) or regenerating (C), the first step in iterative refinement is diagnosing and pinpointing the specific weaknesses in the current output against your criteria.',
  'Revising before diagnosing is guesswork. The sequence is always diagnose → revise → verify → decide.', 'Refinement sequence');

Q('Workflows', I, MC, 'A knowledge worker is adjusting an approach after a two-week pilot identified two specific opportunities for improvement. The pilot\'s core results were positive, and the team is preparing for a broader rollout. Which adjustment is most appropriate?', [
  'Roll out the approach as piloted and address the two opportunities in a separate follow-up project after the rollout completes.',
  'Run a second pilot focused only on the two opportunities, then combine the results of both pilots before rolling out the approach.',
  'Adopt the changes that worked, address the two specific opportunities, and run a controlled comparison before broader rollout.',
  'Adopt the changes that worked, address the two opportunities, and monitor results closely during the broader rollout.'], 3,
  'When a pilot\'s core results are positive and only two improvement areas are identified, retain the working practices, address the two targeted opportunities, and monitor performance closely during rollout.',
  'Running a second full pilot or deferring fixes wastes time when the core approach already works.', 'Pilot refinement');

Q('Code Execution', I, MC, 'A finance manager must select a Claude feature that calculates exact summary totals across a multi-tab spreadsheet. Which selection best fits the requirement?', [
  'Use a standard chat prompt, which passes the spreadsheet contents to the model and asks it to compute the totals across every tab.',
  'Use an Artifact, which renders the calculations as a stable, editable document the manager can review across runs.',
  'Use the Research feature, which gathers figures from multiple sources and assembles them into a summary the manager can review.',
  'Use Code Execution, which runs code in a sandbox to perform calculations on the uploaded file and produce verified outputs the associate can check.'], 3,
  'Language models predict tokens probabilistically and should not be relied upon for exact arithmetic. Code Execution runs deterministic Python code to calculate exact totals that the user can verify.',
  'Chat prompts, Artifacts, and Research are not designed for exact computation. Code Execution is.', 'Code Execution use case');

Q('Code Execution', I, MC, 'An analyst has been asked to compute summary statistics from an uploaded dataset and include a visualization chart in a weekly report. Which output approach best fits the task?', [
  'Request a narrative description of the data in the chat response, describing the general trends without computing exact values.',
  'Ask Claude to estimate the summary statistics from a brief preview of the file rather than the complete uploaded dataset.',
  'Produce a written description of what the chart would show, in place of generating the actual visualization.',
  'Use Code Execution to perform the calculations and generate the chart, then verify the computed results against the source data before sharing the output.'], 3,
  'Computing exact summary statistics and plotting a chart from an uploaded dataset requires deterministic calculation and rendering via Code Execution, followed by verification.',
  'Estimating, describing trends, or describing the chart instead of generating it does not meet the task requirement.', 'Code Execution + verification');

Q('Prompting', I, MC, 'A knowledge worker has noticed that the same weekly status prompt produces noticeably different outputs across runs. Some weeks the output uses the right sections but the wrong tone; other weeks the tone is right but a section is missing. The source inputs change each week, but follow the same structure. Which cause is most worth investigating first?', [
  'The model is non-deterministic, so identical prompts naturally produce different outputs even when the prompt itself is well-written, and the team should accept the variation.',
  'The recurring prompt under-specifies the audience, tone, format, and required sections, so each run drifts depending on what the model emphasizes that turn.',
  'The source inputs vary too much from week to week, and the team should standardize the inputs before changing the prompt.',
  'The team should split the prompt into separate prompts for tone and structure, since combining both in one prompt produces the kind of inconsistency the team is seeing.'], 1,
  'When a recurring prompt produces inconsistent tone or missing sections despite similarly structured inputs, the primary cause is prompt under-specification—failing to explicitly lock in the target audience, tone, format, and required sections.',
  'Accepting variation, splitting the prompt, or blaming input variance misdiagnose the issue. The fix is better specification.', 'Prompt under-specification');

Q('Prompting', B, MC, 'You are an operations assistant asking Claude to present weekly performance metrics across five regional teams for a comparison meeting. Which output format communicates the data most clearly?', [
  'a bulleted list of observations grouped by region without consistent metrics across entries',
  'a narrative summary organized by region, describing trends and notable records in prose',
  'a structured table with one record per row and one metric per column, sorted by region',
  'a series of regional narrative briefs, each describing weekly performance in paragraph form'], 2,
  'When comparing the same set of metrics across five teams, a structured table with one region per row and one metric per column makes cross-regional comparison immediate and scannable.',
  'Bulleted lists, narrative prose, and briefs bury the comparison. Tables surface it.', 'Output format selection');

Q('Model Selection', I, MC, 'You are an analyst working on a one-off complex problem that requires multi-step financial reasoning and an extended chain of thought. Which model is best suited to this work?', [
  'Haiku, because lightweight models are generally preferred for cost and speed, even on tasks that need extended reasoning.',
  'Sonnet, because most tasks perform equally well on the mid-tier model regardless of reasoning complexity.',
  'Opus, because it is positioned as the most capable for advanced reasoning on complex specialized tasks.',
  'Sonnet, because its balanced reasoning is generally adequate and avoids the higher latency associated with Opus.'], 2,
  'For a one-off, high-complexity problem requiring deep multi-step financial reasoning and extended chain of thought, Claude Opus is positioned as the most capable model tier.',
  'Haiku is for simple tasks; Sonnet is for routine production; Opus is for complex one-off reasoning.', 'Model selection');

Q('Projects', I, SEQ, 'You are writing system-level instructions for a Project that supports a recurring team workflow. Which step should be performed first when writing the system-level instructions?', [
  'Draft the system-level instructions using a template from a similar existing Project.',
  'Refine the drafted instructions based on observed gaps from validation runs.',
  'Validate the drafted instructions against representative requests for the Project.',
  'Define the purpose of the Project and the boundaries the instructions must respect.'], 3,
  'Before drafting, validating, or refining system-level instructions for a Claude Project, you must first define the Project\'s core purpose and the operational/policy boundaries those instructions must enforce.',
  'Drafting before defining the purpose leads to instructions that miss the point.', 'Project instruction authoring');

Q('Iteration', I, MC, 'You have iterated a Claude prompt eight times, and the last three versions have produced nearly identical outputs with the same minor flaw. Which conclusion is most appropriate?', [
  'Iteration should continue because a plateau often breaks after several more attempts.',
  'Iteration should stop and the task should be abandoned without communicating to stakeholders.',
  'Iteration has reached diminishing returns and the next step is human review or a different approach.',
  'Iteration should stop and the current output should be accepted as-is, without a human review of the remaining issue.'], 2,
  'When eight iterations and the last three consecutive versions yield nearly identical outputs with the same minor flaw, prompt iteration has hit diminishing returns; the productive next step is applying direct human review/editing or changing the approach.',
  'Continuing to iterate, abandoning the task, or accepting the flaw are all wrong. Human review or a different tool is next.', 'Diminishing returns');

Q('Data Sensitivity', A, MC, 'An HR associate is preparing to use Claude on a workplace investigation task, and organizational policy explicitly states that information from ongoing investigations must not be entered into AI tools. Which response best aligns with the policy?', [
  'Enter the investigation-related information into Claude only after the investigation closes, since the policy applies during the investigation period.',
  'Enter the investigation-related information into Claude in an Incognito chat, since Incognito chats do not retain information and therefore fall outside the policy\'s intent.',
  'Escalate the matter to HR leadership for an approved alternative, and do not enter investigation-related information into Claude in the meantime.',
  'Enter a paraphrased version of the investigation-related information that removes identifying details, since paraphrasing addresses the spirit of the policy.'], 2,
  'When organizational policy strictly prohibits entering ongoing investigation data into AI tools, using Incognito or paraphrasing does not override the policy boundary; you must refrain and escalate for an approved workflow.',
  'Incognito is not an exemption. Paraphrasing is not compliance. Policy boundaries are hard stops.', 'Policy boundaries');

Q('Memory', I, MC, 'After importing context from another AI platform into Claude\'s memory, a knowledge worker notices that some imported details do not appear in subsequent responses. Which explanation is most accurate?', [
  'The import transfers every detail as a rule, and any missing content reflects a deliberate choice by Claude to omit the information rather than the documented experimental nature of imports.',
  'Memory imports are experimental, and Claude might not successfully incorporate all imported content; missing details can be added manually through Settings, Capabilities as a fallback.',
  'Imported memories are stored separately from regular memories and cannot be referenced in any chat, so missing details reflect an architectural separation rather than imperfect import incorporation.',
  'Memory imports overwrite all prior memories on completion, so any details that appear missing must have been deleted by the import process rather than not incorporated during the import itself.'], 1,
  'Memory imports across platforms are experimental and may not incorporate every imported detail automatically; users can manually add any missing preferences or context via Settings.',
  'Imports do not guarantee completeness, do not overwrite existing memories, and imported details are not isolated.', 'Memory imports');

Q('Evaluation', I, ST, 'You are validating evaluation criteria proposed for a Claude-generated business brief. Which two criteria are valid for evaluating a Claude-generated brief? (Select two.)', [
  'alignment of the output with the requested format and length constraints',
  'consistency of the writing style with the organization\'s established tone guidelines',
  'presence of an executive summary section as a structural completeness check',
  'factual accuracy of the claims made against the supplied source material',
  'total word count of the output relative to industry benchmarks for business briefs'], [0, 3],
  'Valid evaluation criteria for a business brief measure adherence to the requested format and length constraints (A) and factual accuracy against the supplied source material (D).',
  'Tone consistency and structural completeness are secondary; word count vs. industry benchmarks is not a valid criterion.', 'Evaluation criteria');

Q('4Ds: Description', I, MC, 'Preparing a stakeholder communication about a proposed Claude use case requires framing aligned to the AI Fluency Framework\'s Description competency. Which framing best reflects Description principles for stakeholder communication?', [
  'Describe what Claude can reliably produce for the use case in detail, and address the human oversight only if a stakeholder raises the question directly.',
  'Describe only the most conservative, worst-case capabilities of the use case, reserving the stronger results as a pleasant surprise once the pilot is underway.',
  'Describe what Claude can reliably produce for the use case, the known limitations, and the human oversight that will remain in place, calibrated to the audience\'s familiarity with AI.',
  'Emphasize the most successful examples of what Claude has produced for similar use cases, and let the audience\'s enthusiasm drive the case for approval.'], 2,
  'Aligned with the Description competency, stakeholder communication should transparently describe what Claude can reliably produce, its known limitations, and the human oversight controls in place, tailored to the audience\'s AI familiarity.',
  'Omitting limitations or oversight, underselling, or overselling all violate Description principles.', 'Description competency');

Q('Workflows', A, SEQ, 'You are a senior analyst using Claude to extract requirements from multiple stakeholder documents. Which is the correct order of steps?\\n(1) Group related requirements and flag conflicts or ambiguities for stakeholder review.\\n(2) Validate the structured output against the original sources for accuracy and completeness.\\n(3) Submit the consolidated inputs to Claude with a structured extraction prompt.\\n(4) Gather and label the source materials so each requirement can be traced.\\n(5) Document the final requirements set with source traceability and status.', [
  '4, 3, 1, 2, 5',
  '1, 4, 3, 2, 5',
  '4, 1, 3, 2, 5',
  '3, 4, 1, 2, 5'], 0,
  'Extracting requirements follows: (4) gather and label source materials first, (3) submit with a structured extraction prompt, (1) group related requirements and flag conflicts, (2) validate against original sources, and (5) document the final set with traceability.',
  'The sequence is prepare sources → extract → group/flag → validate → document.', 'Requirements extraction');

Q('Data Sensitivity', A, ST, 'You are an HR specialist sorting potential AI risks in an HR-adjacent workflow. Which two risks pose the highest ethical concern in an HR-adjacent workflow? (Select two.)', [
  'outputs that systematically disadvantage members of a protected group',
  'inconsistent tone and formatting across internal HR communications sent to employees',
  'a clerical typo in a routine internal calendar invitation',
  'inconsistent use of the company\'s preferred dash style across documents',
  'decisions that materially affect a person\'s employment without human accountability'], [0, 4],
  'In HR workflows, the highest ethical risks involve systematic bias disadvantaging protected groups (A) and automated decisions materially affecting employment without human accountability (E).',
  'Tone inconsistencies, typos, and dash-style errors are not ethical risks.', 'Ethical risks');

Q('Workflows', I, MC, 'You are a knowledge worker who decomposed a draft procedure into fifteen narrow steps and noticed that the output looks fragmented and related ideas were split apart. Which adjustment is most appropriate?', [
  'Consolidate related steps into fewer cohesive sections that group naturally connected ideas.',
  'Reduce the step count by merging steps that occur near each other in sequence.',
  'Group the fifteen steps by the order they appear rather than by which ideas they share.',
  'Add short headings above each of the fifteen steps to visually separate them into named categories.'], 0,
  'Over-decomposing a procedure into fifteen overly narrow steps fragments naturally connected ideas; consolidating related steps into fewer, cohesive sections restores logical flow and readability.',
  'Merging by sequence or adding headings are cosmetic fixes. Consolidation by idea is the structural fix.', 'Over-decomposition');

Q('Projects', I, MC, 'An account representative is configuring a Project for drafting customer incident follow-up messages. The current custom instructions tell Claude to "be empathetic and casual, keep it short, and offer a goodwill credit." The customer-success team has flagged that recent drafts sound too brief, have offered goodwill credits in cases where policy does not allow them, and have used contractions that the brand voice guide prohibits. Which adjustment best aligns the configuration to the use case?', [
  'Replace "be empathetic and casual" with "match the brand voice guide," remove the instruction to offer goodwill credits, and let Claude determine its own length based on the incident.',
  'Keep the existing instructions and add a sentence telling Claude to consult the brand voice guide and the goodwill-credit policy that is attached to the Project knowledge base.',
  'Specify the brand voice attributes (empathetic, formal, no contractions), set a minimum length, and instruct Claude to recommend a goodwill credit only when the attached eligibility policy permits one.',
  'Move the brand voice guide and the goodwill-credit policy into the Project knowledge base and rely on the documents alone to guide tone, length, and credit decisions, without changing the custom instructions.'], 2,
  'To fix drafts that are too brief, use prohibited contractions, and offer unauthorized credits, the custom instructions should explicitly state the required brand voice attributes (empathetic, formal, no contractions), set a minimum length, and require checking the attached eligibility policy before recommending any credit.',
  'Vague instructions ("match the guide") or relying on docs alone without explicit rules leave too much ambiguity.', 'Project instruction tuning');

Q('4Ds: Delegation', I, ST, 'As part of a workflow redesign, a process analyst is deciding which steps to delegate to Claude and which to keep with human staff. Which two criteria most directly inform Delegation decisions? (Select two.)', [
  'The visual complexity of the workflow diagram, since steps with more connections and dependencies are more likely to require human oversight.',
  'The need for human creativity, empathy, or judgment in the step, which indicates whether the task is appropriate for AI delegation or requires the human capabilities Claude cannot provide.',
  'The length of time the workflow has existed in its current form, since well-established processes have been sufficiently validated for AI delegation.',
  'The reversibility of the task and the consequence of an error, which together indicate whether the step is safe to delegate to Claude or should be retained for human decision-making.',
  'The seniority of the team member who currently performs the step, since more senior roles typically involve higher-stakes tasks that warrant human retention.'], [1, 3],
  'Under the Delegation competency, deciding whether to delegate a step to Claude is governed by (1) the need for uniquely human judgment, empathy, or creativity (B) and (2) the reversibility of the task and consequence of an error (D).',
  'Visual complexity, process age, and seniority are not the criteria. The exam tests these two exact criteria.', 'Delegation criteria');

Q('Model Selection', I, MC, 'A knowledge worker is explaining the cost, speed, and capability trade-offs across Claude\'s model family to a colleague. Which generalization correctly describes the trade-off?', [
  'More capable models generally consume less of the rate limit because their reasoning is more efficient, even though they run more slowly than lighter models.',
  'Speed and rate-limit consumption are independent of model capability; the difference between Haiku, Sonnet, and Opus is reasoning depth alone.',
  'Lighter models consume more of the rate limit per request than more capable models, since lighter models require multiple passes to match heavier-model quality.',
  'More capable models generally consume more of the rate limit and run more slowly, while lighter models are faster and consume less of the rate limit.'], 3,
  'Across the Claude model family (Haiku, Sonnet, Opus), more capable models generally run more slowly and consume more of the organization\'s rate limit per request, whereas lighter models run faster and consume less rate-limit capacity.',
  'Efficiency, independence, and multi-pass theories are all wrong. The trade-off is capability/speed/cost.', 'Model trade-off');

Q('Data Sensitivity', I, MC, 'A Claude associate is reviewing a Claude-drafted customer-segment description for an internal marketing brief. One description applies a generalization about a demographic group\'s purchasing behavior that does not hold for individual customers in the segment. Which response is most appropriate?', [
  'Keep the description as written for the internal brief, since internal use does not carry the same risk as external publication of demographic generalizations.',
  'Add a disclaimer to the description, noting that the generalization may not apply to all individuals in the segment, and keep the underlying description unchanged.',
  'Remove the entire customer-segment description from the brief, since any segmentation that involves demographic characteristics is likely to introduce similar issues.',
  'Revise the description to focus on observed behaviors rather than generalizations about people, and validate the revision against actual customer data.'], 3,
  'Under Discernment and responsible AI principles, demographic generalizations unsupported by individual data should be revised—even in internal documents—to focus on observed customer behaviors and validated against actual customer data.',
  'Keeping it for internal use, adding a disclaimer, or removing the whole section do not fix the underlying issue.', 'Bias mitigation');

Q('Evaluation', I, MC, 'A customer-success team member is reviewing a Claude-generated quarterly account report against the agreed deliverable list. The report contains all five required topics, but the renewal-risk section names only one risk factor where the deliverable specification calls for renewal risk to be assessed across pricing, product fit, and stakeholder change. Which conclusion is best supported?', [
  'The report does not meet the deliverable specification because a section that addresses only one of three required risk dimensions counts as a missing section.',
  'The report\'s completeness cannot be assessed from the deliverable specification alone; the customer should review the output and confirm whether the renewal-risk depth is sufficient.',
  'The report meets the deliverable specification because all five required topics appear and the renewal-risk section is present in the output.',
  'The report meets the topic-level requirements but the renewal-risk section is under-scoped against the specification and should be expanded before delivery.'], 3,
  'All five topics are present but the renewal-risk section covers only one of the three specified dimensions (pricing, product fit, stakeholder change), so the report meets topic-level presence but is under-scoped and must be expanded.',
  'Presence is not completeness. The spec requires three risk dimensions; the output has one.', 'Completeness vs. presence');

Q('Data Sensitivity', I, ST, 'You are an HR specialist reviewing data items proposed for inclusion in a routine Claude prompt. Which two data items are appropriate to include in a Claude prompt for a routine task? (Select two.)', [
  'a compensation band summary that includes employee names and current salary figures for a specific team',
  'a redacted job description that the model will adapt for a posting',
  'an anonymized summary of an HR policy that the model will rephrase',
  'accommodation request notes from an employee\'s HR file needed to draft a role adjustment memo',
  'employee ID numbers and hire dates for the team roster included to help Claude personalize onboarding communications'], [1, 2],
  'For routine prompts, only redacted job descriptions (B) and anonymized policy summaries (C) are safe to include; named employee salary figures (A), personal medical/accommodation notes (D), and employee PII/IDs (E) must be excluded or redacted.',
  'Compensation + names, accommodation notes, and employee IDs are all PII that require redaction or exclusion.', 'Data classification');

Q('Data Sensitivity', B, MC, 'You are a knowledge worker preparing inputs for a Claude prompt. Which data type most clearly requires extra handling such as redaction or anonymization before being included in the prompt?', [
  'customer government identifiers and full payment-card numbers tied to named individuals',
  'public press releases the company has already published',
  'generic product descriptions available on the company\'s marketing site',
  'job titles taken from the company\'s public organizational chart'], 0,
  'Customer government identifiers and full payment-card numbers tied to named individuals constitute highly sensitive PII/PCI data requiring strict redaction or anonymization before prompting.',
  'Public press releases, marketing copy, and public org-chart titles are not sensitive.', 'PII identification');

Q('Use Case Appropriateness', I, ST, 'You are an operations lead sorting proposed Claude use cases by whether human review or human-only execution is needed. Which two proposed use cases are acceptable for the team to pursue with Claude? (Select two.)', [
  'drafting an internal training summary from approved internal documentation',
  'synthesizing themes across approved customer feedback under aggregation rules',
  'drafting a legal summary an attorney reviews before sharing with a client',
  'drafting a preliminary symptom summary to support a clinician\'s diagnostic review',
  'summarizing performance review notes to determine promotion decisions across a team'], [0, 1],
  'Drafting an internal training summary from approved docs (A) and synthesizing themes from approved customer feedback under aggregation rules (B) are low-risk, appropriate use cases. Determining promotions (E) or clinical/legal practice without specialized governance requires strict human-only or domain structure.',
  'Promotion decisions and clinical/legal summaries cross into high-consequence domains that require human accountability.', 'Use case safety');

Q('Prompting', I, MC, 'A marketing manager is preparing a constrained brainstorming prompt with Claude to generate campaign ideas tailored to a defined audience segment and one of three defined budget bands. Which prompting approach fits the task?', [
  'Ask Claude for thirty ideas with the audience and budget constraints stated in the prompt, then keep the strongest ten so a wider initial pool produces stronger finalists.',
  'Ask Claude for ten distinct ideas with the audience and budget constraints stated in the prompt and require each idea to name which audience and budget band it addresses.',
  'Ask Claude for ten distinct ideas, stating the audience constraints in the prompt and leaving budget unconstrained so creativity is not limited at the ideation stage.',
  'Ask Claude for ten distinct ideas without budget constraints, then filter the output afterward to keep only the ideas that fit the three budget bands.'], 1,
  'For constrained brainstorming across a defined audience segment and three budget bands, asking for ten distinct ideas with the constraints stated upfront and requiring each idea to explicitly label its target audience and budget band ensures structured, directly usable output.',
  'Generating thirty then filtering, or leaving constraints out and filtering later, wastes effort. State constraints upfront.', 'Constrained ideation');

Q('Use Case Appropriateness', I, MC, 'An operations assistant is using Claude to support process optimization for an incoming intake workflow. The assistant has access to the current documentation and recent cycle-time data. Which activity best uses Claude to support this process-optimization task?', [
  'Generate an optimized version of the intake process based on industry benchmarks, then compare it to the current process to identify gaps.',
  'Map the current intake process, identify likely bottlenecks based on the cycle-time data, and propose optimization options for human review.',
  'Apply Claude to predict the cycle-time impact of each proposed change and rank them so the team can implement improvements in priority order.',
  'Use Claude to interview each team member who works on the intake process and synthesize the interview output into a redesigned workflow.'], 1,
  'Claude supports process optimization best by mapping the documented intake workflow, analyzing the provided cycle-time data to surface likely bottlenecks, and proposing optimization options for human review and decision-making.',
  'Generating solutions from benchmarks, predicting impact, or conducting interviews are not appropriate delegation.', 'Process optimization');

Q('Data Sensitivity', I, SEQ, 'You are a compliance specialist applying the organization\'s AI policy to a proposed Claude use case. Which policy-application step should be performed first?', [
  'Compare the proposed use case against the applicable policy provisions.',
  'Approve, modify, or reject the proposed use case based on the comparison.',
  'Identify which policy provisions apply to the proposed use case.',
  'Document the use case and the policy decision in the compliance register.'], 2,
  'When applying organizational AI policy to a proposed use case, the mandatory first step is identifying which specific policy provisions govern that use case before comparing, approving/rejecting, or logging the decision.',
  'Identify provisions → compare → decide → document is the sequence.', 'Policy application');

Q('Use Case Appropriateness', I, ST, 'You are a project manager reviewing Claude usage across a project workflow. Which two workflow steps are well-suited for Claude support? (Select two.)', [
  'drafting a structured project status update from a set of meeting notes',
  'issuing legally binding contractual commitments on behalf of the company',
  'synthesizing a literature review across many uploaded research documents',
  'approving a final external press release without any human review',
  'deciding promotion outcomes for staff based solely on the model\'s judgment'], [0, 2],
  'Drafting a structured project status update from meeting notes (A) and synthesizing a literature review across uploaded research documents (C) leverage Claude\'s summarization and synthesis strengths while keeping humans in control.',
  'Binding legal commitments, unreviewed press releases, and promotion decisions are not appropriate for delegation.', 'Appropriate delegation');

Q('Evaluation', I, MC, 'You are a customer-success manager considering whether to escalate a Claude-generated response before external use. Which factor most strongly raises the impact of the output and supports escalation before external use?', [
  'The response is an internal draft summarizing the associate\'s notes from a customer call for their own reference.',
  'The response is a casual rephrasing of an internal team status update.',
  'The response is an unchanged draft for a paying customer that includes a service-level commitment.',
  'The response is a brief internal announcement about an upcoming team all-hands meeting.'], 2,
  'An unchanged draft sent externally to a paying customer that includes a service-level commitment carries high financial, legal, and reputational impact, requiring escalation and human sign-off prior to external use.',
  'Internal drafts for your own reference, casual internal updates, and meeting announcements are low-impact.', 'Escalation criteria');

Q('Iteration', I, MC, 'You are an operations lead choosing actions when a long Claude conversation starts losing coherence across turns. Which recovery action should be tried first when conversation quality degrades?', [
  'Replace the model with a different vendor\'s model right away.',
  'Summarize the current state and continue with a focused follow-up prompt.',
  'Discard the entire conversation and rebuild the work from the original prompt.',
  'Escalate to a senior architect for a manual review of the conversation history.'], 1,
  'When a multi-turn conversation begins losing coherence due to context growth, the most effective first recovery step is summarizing the current state and continuing with a focused follow-up prompt.',
  'Replacing the model, discarding everything, or escalating are overreactions. Summarize + focus is the right first step.', 'Context recovery');

Q('Prompting', I, ST, 'You are a project manager designing a checklist for evaluating prompt quality across a team. Which two items belong on the prompt-quality checklist? (Select two.)', [
  'whether the prompt includes the names of every person in the department',
  'whether the prompt reaches a thousand words, whatever it actually says',
  'whether the prompt uses the author\'s favorite opening phrase as a signature',
  'whether the prompt states a specific task with the required deliverable',
  'whether the prompt provides relevant context including audience and goal'], [3, 4],
  'A team prompt-quality checklist should verify that every prompt clearly states a specific task with the required deliverable (D) and supplies relevant context such as target audience and goal (E).',
  'Listing everyone, hitting a word count, or using a signature phrase are not quality criteria.', 'Prompt quality');

Q('Projects', I, MC, 'A learning specialist is configuring a Claude Project for a recurring course-design workflow. Which configuration approach best leverages a Skill alongside other Project elements?', [
  'Configure the Project with custom instructions that describe a different workflow than the one the Skill documents.',
  'Upload the supporting knowledge sources but leave the relevant Skill disabled, relying on custom instructions alone.',
  'Add the Skill and the supporting knowledge sources to the Project, but write custom instructions for a general use case unrelated to the recurring course-design workflow the Skill documents.',
  'Add the relevant Skill to the Project, upload the supporting knowledge sources, and write custom instructions that reference both the Skill and the knowledge.'], 3,
  'To leverage a Skill effectively inside a Claude Project, you should enable/add the relevant Skill to the Project, upload the supporting reference documents to Project knowledge, and write custom instructions that explicitly coordinate how Claude should use both the Skill and the knowledge sources.',
  'Contradicting the Skill, disabling it, or writing unrelated instructions waste the Skill.', 'Skill integration');

Q('Data Sensitivity', B, SEQ, 'You are handling a document containing mixed sensitive and non-sensitive data before using it with Claude. Which data-handling step should be performed first?', [
  'Classify the content of the document and identify which fields are sensitive.',
  'Redact sensitive fields and replace them with appropriate placeholders.',
  'Review the redacted document with a peer to confirm the redaction is complete.',
  'Submit the redacted document to Claude for the intended task.'], 0,
  'Before redacting (B), peer-reviewing (C), or submitting (D), the mandatory first step is classifying the document\'s contents and identifying which specific fields are sensitive.',
  'The sequence is classify → redact → peer-review → submit.', 'Data handling sequence');

Q('Prompting', I, MC, 'You are an analyst reviewing a Claude response that answered two of three required questions and skipped the third. Which prompt element most likely needs strengthening?', [
  'The context provided to Claude should be expanded with additional background detail about the subject matter.',
  'The task statement should explicitly enumerate the three required questions and require an answer to each.',
  'The output format should be revised to allow Claude to determine the appropriate structure for each question\'s answer.',
  'The role assigned to Claude should be changed to a more specialized expert persona to increase response depth.'], 1,
  'When Claude answers two questions in a prompt and skips the third, strengthening the task statement to explicitly enumerate all three required questions and require a separate answer to each directly prevents partial completion.',
  'Context, format, and role are not the issue. The task statement must list all three questions.', 'Task completeness');

Q('Projects', I, MC, 'A senior manager is reviewing a colleague\'s habit of never updating their Project\'s custom instructions because "if it works once, it works forever." Which feedback is most warranted?', [
  'Configurations should be left alone if the team is satisfied with current outputs, and any required updates should be handled at the chat level rather than the Project level.',
  'Configurations should be reviewed and updated periodically because policies, terminology, and source documents change over time, even when output quality has not visibly degraded.',
  'Configurations should be updated on a fixed schedule, since regular maintenance prevents drift even when nothing about the policies or source documents has changed.',
  'Configurations should be updated only when output quality visibly degrades, since proactive updates risk introducing regressions in working configurations.'], 1,
  'Even if a Project\'s output quality has not visibly broken, organizational policies, terminology, and reference documents evolve over time; therefore, Project configurations and custom instructions should be reviewed and updated periodically to prevent silent drift.',
  'Leaving it alone, updating on a fixed schedule, or waiting for visible degradation are all wrong. Review when policies change.', 'Configuration maintenance');

Q('Workflows', I, MC, 'You are evaluating whether a "redesign new-hire onboarding" request should be decomposed before prompting Claude. Which feature of the request most strongly indicates decomposition will help?', [
  'The request is for a single structured document that can be produced from one set of inputs in one prompt.',
  'The request covers content the associate has produced many times before in a familiar format.',
  'The request involves a single well-defined output with a clear input and a familiar format.',
  'The request requires multiple distinct outputs: a process map, supporting materials, and a measurement plan.'], 3,
  'Task decomposition is most beneficial when a single broad request ("redesign new-hire onboarding") actually requires multiple distinct deliverables—such as a process map, supporting training materials, and a measurement plan—each benefiting from a focused prompt.',
  'Single structured documents, familiar content, and single outputs do not need decomposition.', 'Decomposition signal');

Q('Evaluation', I, ST, 'You are designing a checklist for evaluating Claude outputs in a recurring workflow before scoring an output. Which two steps must be completed BEFORE scoring a Claude output against the checklist? (Select two.)', [
  'Forward unacceptable outputs to a senior reviewer for second-pass review.',
  'Document the final scoring rubric and reviewer comments for the audit trail.',
  'Specify the threshold that distinguishes acceptable from unacceptable output.',
  'Promote the approved output into the downstream production process.',
  'Define the evaluation criteria that matter for the task at hand.'], [2, 4],
  'Before scoring any Claude output against an evaluation checklist, you must first define the evaluation criteria that matter for the task (E) and specify the passing threshold that separates acceptable from unacceptable output (C).',
  'Forwarding, documenting, and promoting all happen after scoring.', 'Evaluation sequence');

Q('4Ds: Description', I, MC, 'A project lead is preparing a presentation for an executive sponsor who will be asked to approve continued investment based on the presentation. Which framing best balances value and limitations?', [
  'Describe Claude\'s capabilities in technical terms so the sponsor understands the underlying model, and let the sponsor draw their own conclusions about value and limitations.',
  'Describe what Claude does well, name the limitations the team will manage with human review, and tie both to the project outcomes the sponsor cares about.',
  'Describe what Claude does well and tie it to the project outcomes; defer discussion of limitations to a follow-up conversation to keep the approval discussion focused.',
  'Describe the limitations first to set expectations, then explain how the team works around each limitation to deliver the project outcomes despite them.'], 1,
  'When presenting to an executive sponsor for investment approval, balanced framing describes what Claude does well, transparently names the limitations the team will mitigate through human review, and connects both directly to the business outcomes the sponsor cares about.',
  'Technical terms, deferring limitations, or leading with limitations all misframe the discussion.', 'Executive framing');

Q('Model Selection', A, SEQ, 'You are a project lead at Jasper Traders aligning model selection to a recurring business workflow. Which is the correct order of alignment steps?\\n(1) Run a representative sample on the candidate model and measure quality, latency, and rate-limit consumption.\\n(2) Select the lightest model that consistently meets the bar across the sample.\\n(3) Define the quality bar, latency tolerance, and expected volume for the workflow.\\n(4) Choose a candidate model based on the requirements profile.\\n(5) Retest the choice when a new model becomes available.', [
  '3, 4, 1, 2, 5',
  '1, 3, 4, 2, 5',
  '4, 3, 1, 2, 5',
  '3, 1, 4, 2, 5'], 0,
  'Aligning model selection to a recurring workflow follows: (3) define the quality bar, latency tolerance, and expected volume, (4) choose a candidate model based on that profile, (1) run a representative sample and measure quality/latency/rate-limit usage, (2) select the lightest model that consistently meets the bar, and (5) retest when new models launch.',
  'Define requirements → choose candidate → test → select lightest passing → retest is the sequence.', 'Model selection sequence');

Q('4Ds: Discernment', I, MC, 'You are a communications manager validating a Claude-drafted external newsletter that cites a striking industry growth figure. The figure appears in three trade-press articles, but none of them link to the underlying study. Which validation step is correct?', [
  'Remove the source attribution and present the figure as common knowledge already familiar to the newsletter\'s readers.',
  'Accept the figure because three trade-press articles repeat the same number independently of one another.',
  'Use the highest figure across the three articles to make the newsletter more compelling.',
  'Locate the original study referenced by the trade-press articles and verify the figure in the primary source.'], 3,
  'When secondary trade-press articles repeat a striking statistic without linking the study, proper fact-checking requires locating the original primary study and verifying the figure directly in the primary source.',
  'Removing attribution, accepting repetition, or using the highest figure are all wrong. Verify against the primary source.', 'Primary source verification');

Q('Projects', I, MC, 'A learning specialist is configuring a Project for course-design tasks that must follow organizational instructional-design standards and a preferred output structure for lesson outlines. Which custom-instruction set best supports this use case?', [
  'Specify only the preferred output structure for lesson outlines, since the structure implies the standards implicitly and naming the role adds no value.',
  'Name Claude\'s role as a course designer and require alignment to the organization\'s instructional-design standards; leave output structure to Claude based on the topic of each lesson.',
  'Name Claude\'s role as a course designer; let each chat\'s prompt specify the standards and output structure for that lesson, since lessons vary widely.',
  'Name Claude\'s role as a course designer, require alignment to the organization\'s instructional-design standards, and specify the preferred output structure for lesson outlines.'], 3,
  'For a recurring course-design Project, custom instructions should assign Claude\'s role as a course designer, require adherence to the organization\'s instructional-design standards, and specify the exact preferred output structure for lesson outlines.',
  'Leaving out the role, standards, or structure creates variance. All three are needed.', 'Project instruction design');

Q('Workflows', I, SEQ, 'You are a marketing manager using Claude to research a new market segment. Which research step should be performed first?', [
  'Submit a series of Claude prompts to gather information across the segment.',
  'Generate a final research report combining every Claude output produced.',
  'Define the specific research questions that must be answered for the segment.',
  'Validate the gathered information against authoritative external sources.'], 2,
  'Before submitting prompts (A), validating findings (D), or compiling a final report (B), any structured research effort must begin by defining the specific research questions that need to be answered for the market segment.',
  'Define questions → gather → validate → report is the sequence.', 'Research sequence');

Q('Prompting', I, MC, 'A finance consultant is adapting a Claude-generated quarterly summary for senior executives who have limited time and need the headline result and forward outlook to be clear early. Which adaptation is most appropriate for this audience?', [
  'Lead with the forward outlook, since investors are most interested in what comes next, and present the headline result and drivers afterward.',
  'Lead with a chronological recap of the quarter\'s events, reaching the headline result only near the end, then close with the outlook.',
  'Lead with the quarter\'s operational highlights, present the financial result in the middle for context, and close with the forward outlook.',
  'Lead with the headline result, present the key drivers concisely, and close with the forward outlook.'], 3,
  'Time-constrained senior executives need bottom-line-up-front (BLUF) communication: lead immediately with the headline financial result, concisely present the key drivers, and close with the forward outlook.',
  'Leading with outlook, chronology, or operational highlights buries the headline.', 'Audience adaptation');

Q('Prompting', I, ST, 'You are a business analyst reviewing prompt best practices with new team members. Which two elements belong in a well-structured prompt for a business task? (Select two.)', [
  'a clear statement of the task that the model must perform',
  'relevant context such as the audience and the goal of the task',
  'a friendly, conversational tone instruction to make responses feel more approachable',
  'a short personal anecdote to make the prompt feel more conversational',
  'a comprehensive list of company products and services to provide the model with business context'], [0, 1],
  'A well-structured business prompt fundamentally requires a clear statement of the task the model must perform (A) and relevant context such as the target audience and business goal (B).',
  'Tone instructions, personal anecdotes, and product lists are not core elements.', 'Prompt elements');

Q('Projects', I, MC, 'A manager is monitoring a Project\'s effectiveness over time. The Project was configured six months ago to support a recurring workflow. Which signal most directly suggests the configuration needs updating?', [
  'The Project\'s outputs have grown longer on average than the outputs produced when the Project was first configured.',
  'The Project\'s chat volume has decreased steadily over the past several weeks compared to the prior baseline.',
  'The Project\'s outputs increasingly reference terminology, sources, or guidance that no longer reflects current practice.',
  'The Project\'s members have started using ad-hoc chats outside the Project for tasks within the Project\'s scope.'], 2,
  'The clearest signal that a six-month-old Project configuration needs updating is when its outputs increasingly cite outdated terminology, sources, or guidance that no longer reflects current organizational practice.',
  'Longer outputs, lower chat volume, and ad-hoc chats are ambiguous signals. Outdated terminology is the direct signal.', 'Configuration drift');

Q('Evaluation', I, MC, 'You are a Claude associate troubleshooting a Claude-generated summary that includes claims not supported by the supplied source. Which root cause is most directly indicated?', [
  'The prompt does not constrain Claude to use only facts present in the supplied source.',
  'The prompt asks for a comprehensive response, which leads Claude to fill perceived gaps with plausible-sounding but unverified detail.',
  'The prompt asks Claude to act as a researcher rather than a writer.',
  'The prompt\'s heading-based structure encourages Claude to generate placeholder content under each heading even when the source doesn\'t cover it.'], 0,
  'When a summary includes claims not supported by the supplied source document, the most direct root cause in prompt design is failing to explicitly constrain Claude to rely only on facts present in the supplied source.',
  'Comprehensive requests, role, and headings are indirect. The missing constraint is the direct cause.', 'Hallucination root cause');

Q('Iteration', I, MC, 'A sales manager is iterating on a Claude-generated sales-deck prototype after reviewers raised two specific concerns; the rest of the prototype was accepted as written. Which iteration approach is most likely to produce a strong next version?', [
  'Address the two specific concerns directly, leave unrelated parts unchanged, and document the changes for the next review.',
  'Address the two specific concerns and also revise unrelated sections to maintain consistent voice across the prototype after the edits.',
  'Address the two specific concerns and add a third improvement the sales manager identified.',
  'Rewrite the prototype from scratch incorporating the two specific concerns.'], 0,
  'When reviewers accept a prototype except for two specific concerns, disciplined iteration addresses those two concerns directly, leaves accepted sections unchanged to avoid introducing regressions, and documents the changes for the next review.',
  'Revising unrelated sections, adding unrequested changes, or rewriting from scratch risk regressions.', 'Disciplined iteration');

Q('Prompting', I, MC, 'A knowledge worker is explaining context-window behavior to a colleague. Which statement most accurately describes a context window?', [
  'a bounded amount of text the model can consider at once, including the conversation history, attached documents, and the current input.',
  'the complete conversation history retained across sessions, which the model can reference whenever it produces a response in any chat.',
  'the subset of the conversation that the model determines is most relevant to the current input, which can be smaller than the full conversation.',
  'an adjustable setting that determines how much of the conversation history the model includes in each response, configurable per chat.'], 0,
  'A model\'s context window is the bounded amount of text (tokens) the model can consider at one time in a single request, encompassing the system instructions, conversation history, attached documents, and current user input.',
  'It is not retained across sessions, not dynamically selected, and not adjustable per chat.', 'Context window definition');

Q('4Ds: Diligence', A, MC, 'A Claude associate is applying the AI Fluency Framework\'s Diligence competency across their daily workflows. Which practice best reflects Diligence in a governance context?', [
  'Apply organizational AI policies during onboarding as a foundational training step, document that each associate has reviewed them, and treat that record as evidence of ongoing compliance.',
  'Apply the organizational AI policies only in high-visibility situations where usage is likely to be observed or reviewed by others.',
  'Apply organizational AI policies consistently as a sustained professional habit, identify gaps between actual usage and the policies, and take corrective action to close those gaps over time.',
  'Defer all policy application to a centralized compliance team, treating individual usage as outside personal responsibility.'], 2,
  'Under the AI Fluency Framework, Diligence in governance means applying organizational AI policies consistently as a sustained professional habit, proactively spotting gaps between actual practice and policy, and taking corrective action over time.',
  'One-time onboarding, high-visibility-only, and deferring to compliance are not Diligence.', 'Diligence in governance');

Q('Prompting', I, MC, 'A project manager is transforming a Claude-generated project update into an executive brief for a board meeting, and expects it to be scannable, factually verified, and consistent with the organization\'s standard terminology. Which set of refinements is most appropriate?', [
  'Apply consistent headings, expand each section to give the board full context, and align terminology with the organization\'s standards.',
  'Apply consistent headings, tighten wording for executive scannability, align terminology with the organization\'s standards, and verify each fact against source data.',
  'Tighten wording for executive scannability and verify each fact against source data; leave heading structure and terminology as written to preserve the draft\'s voice.',
  'Apply consistent headings and align terminology with the organization\'s standards; rely on Claude\'s verification of facts, since the draft was generated from the source data.'], 1,
  'Transforming a raw project update into a board-ready executive brief requires applying consistent headings, tightening prose for executive scannability, aligning terminology with organizational standards, and independently verifying every fact against source data.',
  'Expanding sections, leaving headings/terminology as-is, or trusting Claude\'s verification are wrong.', 'Executive brief refinement');

Q('Iteration', I, MC, 'You are a content creator. A first response from Claude uses terminology that is inconsistent with your organization\'s glossary. Which iterative change addresses the issue most directly?', [
  'Ask Claude to review the response for consistent terminology without providing the organization\'s glossary as a reference.',
  'Generate the response first, then manually find-and-replace mismatched terms afterward instead of supplying the glossary upfront.',
  'Ask Claude to choose terminology it judges most appropriate, without referencing the organization\'s established glossary.',
  'Provide the organization\'s glossary and instruct Claude to use only those terms throughout the response.'], 3,
  'When Claude uses terminology inconsistent with your organization\'s glossary on a first draft, the most direct iterative fix is providing the organization\'s glossary in context and instructing Claude to use only those approved terms.',
  'Asking Claude to self-review, manual find-replace, or choosing its own terms do not fix the root cause.', 'Terminology alignment');

Q('Evaluation', I, SEQ, 'You are evaluating a Claude output that appears to contain a hallucinated claim. Which response step should be performed first when a hallucination is suspected?', [
  'Document the hallucination pattern in the team\'s risk register for future reference.',
  'Notify the user community that the output contains a hallucinated claim.',
  'Pinpoint the specific claim that appears to be unsupported by available evidence.',
  'Discard the entire output and regenerate the output with a fresh prompt.'], 2,
  'When a hallucinated claim is suspected in a Claude output, the mandatory first step is pinpointing the exact claim that appears unsupported by available evidence so it can be verified against authoritative sources before deciding how to correct or escalate.',
  'Documenting, notifying, or discarding all come after pinpointing and verifying the suspected claim.', 'Hallucination triage');
